VALUES ('526cc453-0612-5f0d-86a0-bedc97e9df3d', 'shopInfo', '{"name":"35女王古殿","shortName":"Twilight Salon","subtitle":"一處替旅人留燈的深夜貴賓廳，提供陪伴、談心、占卜與沉浸式 RP 接待。","businessStatus":"今日營業 21:30 開席","openHours":"每週五、六 21:30 - 24:00","server":"Elemental / Aegis","address":"薰衣草苗圃 第 12 區 斜坡小屋","entryNote":"入場前請先閱讀消費說明與 RP 禮儀","about":["35女王古殿是一間以深夜貴賓廳為主題的 FF14 RP 店，提供陪談、指名陪伴、活動企劃與角色沉浸式互動。","我們位於 Elemental / Aegis，薰衣草苗圃第 12 區斜坡小屋，歡迎想放慢腳步的冒險者入席。","店內重視彼此尊重與舒適節奏，第一次來訪也可以由店員協助說明入場、指名與拍照流程。"],"footerText":"燭火、杯影與低聲的故事，為每位來訪者保留一席安靜的夜晚。","heroImage":"https://imagefaker.access.mx.com/1400x900/15151c/ff2e88/?text=35%E5%A5%B3%E7%8E%8B%E5%8F%A4%E6%AE%BF%20Hero&font=noto","pricingNote":"第一版價格為 demo mock data，正式營運前可由後台或 API 維護。","pricing":[{"name":"入場席費","price":"30,000 Gil"},{"name":"指名陪伴","price":"50,000 Gil / 30min"},{"name":"包廂預約","price":"120,000 Gil / 場"}]}', '現行 Web 首頁、導覽與頁尾店舖資訊。', TRUE, '2026-07-01 20:00:00', '2026-07-01 20:00:00')
ON DUPLICATE KEY UPDATE `SETTING_KEY` = VALUES(`SETTING_KEY`), `SETTING_VALUE` = VALUES(`SETTING_VALUE`), `DESCRIPTION` = VALUES(`DESCRIPTION`), `IS_ACTIVE` = VALUES(`IS_ACTIVE`), `UPDATED_AT` = VALUES(`UPDATED_AT`);
