VALUES ('7e50f7a4-c476-5158-9d5e-6f994b76a983', '月下祝杯夜', '以月光、低酒精調飲與雙人短談為主題的週末限定場。', 'https://imagefaker.access.mx.com/1400x900/15151c/ff2e88/?text=%E6%9C%88%E4%B8%8B%E7%A5%9D%E6%9D%AF%E5%A4%9C&font=noto', '2026-07-03 00:00:00', '2026-07-04 23:59:59', 'active', NULL, '["活動期間每位來客可獲得一張月色籤詩，由當班店員依籤詩延伸一段短篇 RP。","本場適合想輕量體驗陪談、初次入店或與朋友一起參與的客人。","包廂名額有限，建議提前於店舖動態確認當週安排。"]', NULL, 0, TRUE, '2026-07-01 20:00:00', '2026-07-01 20:00:00')
ON DUPLICATE KEY UPDATE `TITLE` = VALUES(`TITLE`), `SUMMARY` = VALUES(`SUMMARY`), `COVER_IMAGE_URL` = VALUES(`COVER_IMAGE_URL`), `STARTS_AT` = VALUES(`STARTS_AT`), `ENDS_AT` = VALUES(`ENDS_AT`), `STATUS` = VALUES(`STATUS`), `LOCATION_TEXT` = VALUES(`LOCATION_TEXT`), `DETAIL_CONTENT` = VALUES(`DETAIL_CONTENT`), `NOTICE_CONTENT` = VALUES(`NOTICE_CONTENT`), `SORT_ORDER` = VALUES(`SORT_ORDER`), `IS_PUBLISHED` = VALUES(`IS_PUBLISHED`), `UPDATED_AT` = VALUES(`UPDATED_AT`);
