VALUES ('66e1f001-3f05-51db-b101-d6d505a0782e', '水晶留信企劃', '替指定角色留下一封匿名短箋，活動結束後由店員朗讀或轉交。', 'https://imagefaker.access.mx.com/1400x900/15151c/ff2e88/?text=%E6%B0%B4%E6%99%B6%E7%95%99%E4%BF%A1%E4%BC%81%E5%8A%83&font=noto', '2026-06-21 00:00:00', '2026-07-12 23:59:59', 'active', NULL, '["客人可在店內填寫一封不含現實個資的角色短箋，指定公開朗讀或私下轉交。","內容需符合店內 RP 禮儀，工作人員會保留審核與婉拒權利。"]', NULL, 1, TRUE, '2026-07-01 20:00:00', '2026-07-01 20:00:00')
