VALUES ('9cb9b9a0-9bfa-5819-89ee-9234d0d293b3', '女王花園茶會', '以雙人茶席、輕量角色訪談與庭園拍照為主軸的午後系夜場。', 'https://imagefaker.access.mx.com/1400x900/15151c/ff2e88/?text=%E5%A5%B3%E7%8E%8B%E8%8A%B1%E5%9C%92%E8%8C%B6%E6%9C%83&font=noto', '2026-07-18 00:00:00', '2026-07-19 23:59:59', 'scheduled', NULL, '["活動期間會開放花園主題茶席，店員會依來客角色設定安排一段短篇迎賓對話。","本場適合想拍攝紀念照、體驗低壓互動，或與朋友一起入席的客人。","茶席名額依當日店員人力調整，正式預約請以店舖動態公告為準。"]', NULL, 2, TRUE, '2026-07-01 20:00:00', '2026-07-01 20:00:00')
