VALUES ('4a885c62-61b3-5111-a5e4-c23c7afdb4d5', '午夜神諭占卜夜', '由當班店員以籤詩與角色提問延伸一段沉浸式占卜互動。', 'https://imagefaker.access.mx.com/1400x900/15151c/ff2e88/?text=%E5%8D%88%E5%A4%9C%E7%A5%9E%E8%AB%AD%E5%8D%A0%E5%8D%9C%E5%A4%9C&font=noto', '2026-07-25 00:00:00', '2026-07-26 23:59:59', 'scheduled', NULL, '["來客可準備一個角色內問題，由店員抽取神諭籤並給予一段可延伸 RP 的回應。","占卜內容以角色敘事與氣氛演出為主，不涉及現實人生、健康或財務判斷。","若客人希望保留結果，可於活動後至留聲機留下角色回饋。"]', NULL, 3, TRUE, '2026-07-01 20:00:00', '2026-07-01 20:00:00')
