VALUES ('83579629-c61c-5a0c-aee6-80017a6ff0c8', '燼火小舞會', '已結束的舞會主題夜，保留給想回顧規則與照片的客人。', 'https://imagefaker.access.mx.com/1400x900/15151c/ff2e88/?text=%E7%87%BC%E7%81%AB%E5%B0%8F%E8%88%9E%E6%9C%83&font=noto', '2026-05-24 00:00:00', '2026-05-25 23:59:59', 'ended', NULL, '["燼火小舞會已結束，第一版 demo 保留一個失效活動案例。","過期超過一個月的活動會在前端資料層排除，不再顯示於列表。"]', NULL, 4, FALSE, '2026-07-01 20:00:00', '2026-07-01 20:00:00')
